                    for i in range(k): s1[i] += 1
                    for i in range(k, M): s1[i] -= 1
                    s1 = tuple(s1)
                    s2 = list(s)
                    for i in range(k): s2[i] -= 1
                    for i in range(k, M): s2[i] += 1
                    s2 = tuple(s2)

                    if s1 not in W and s2 not in W:
                        is_w = False
                        break
                if is_w:
                    new_W.add(s)
            if new_W == W:
