    # A state s is Bad if there exists k such that for all sigma, s' is Bad.
    # Alice chooses sigma to keep s' Good.
    # If there exists sigma such that s' is Good, then s is Good.

    # Let's only consider states with sum <= max_S.
    # If s' has sum > max_S, we'll treat it as Good.

    bad_states = set()

    # Initial Bad states: any state with some x_i = 0 and sum <= max_S.
    for s_sum in range(max_S + 1):
        for combo in itertools.product(range(max_S + 1), repeat=M):
            if sum(combo) == s_sum:
                if any(x == 0 for x in combo):
                    bad_states.add(combo)

    while True:
        added = False
        for s_sum in range(max_S + 1):
            for combo in itertools.product(range(max_S + 1), repeat=M):
                if sum(combo) == s_sum and combo not in bad_states:
                    for k in range(1, M):
                        sigma_all_bad = True
                        for sigma in [1, -1]:
                            new_s = list(combo)
                            for i in range(M):
                                if i < k:
                                    new_s[i] += sigma
                                else:
                                    new_s[i] -= sigma

                            new_s_tuple = tuple(new_s)
                            s_new_sum = sum(new_s_tuple)

