def find_min_S_for_N(N):
    for S in range(1, 200):
        # Try to see if there is any state with sum S that is safe.
        # A state m is safe if for all k, there exists sigma s.t. m' >= 0 and m' is safe.
        # Since sum(m') <= sum(m) can be achieved by Alice, 
        # we only need to check if m' is safe in the set of states with sum <= S.

        # Let's find the set of safe states for a given S.
        # A state m is safe if for all k, there exists sigma s.t. m' >= 0 and m' is safe.
        # This is a fixed-point.

        limit = S
        states = []
        def generate(n, s, current):
            if n == 1:
                states.append(tuple(current + [s]))
                return
            for i in range(s + 1):
                generate(n - 1, s - i, current + [i])
        for s in range(limit + 1):
            generate(N, s, [])

        safe_set = set(states)
        while True:
            to_remove = set()
            for m in safe_set:
                is_m_safe = True
                for k in range(1, N):
                    found_sigma = False
                    for sigma in [1, -1]:
                        m_prime = list(m)
                        for j in range(N):
                            if j < k:
                                m_prime[j] += sigma
                            else:
                                m_prime[j] -= sigma
                        if all(x >= 0 for x in m_prime) and tuple(m_prime) in safe_set:
                            found_sigma = True
                            break
                    if not found_sigma:
                        is_m_safe = False
                        break
                if not is_m_safe:
                    to_remove.add(m)
            if not to_remove:
                break
            safe_set -= to_remove

        # Check if there's any state with sum exactly S in safe_set.
        for m in safe_set:
            if sum(m) == S:
                return S
    return None

